import type { VitePWAOptions } from 'vite-plugin-pwa';

/** Header colour (brand-800): browser UI and the installed app's title bar use it. */
export const THEME_COLOR = '#244e39';

/**
 * Installable app (PWA) settings for vite-plugin-pwa.
 * - Manifest: name, icons (generated by `npm run icons`), standalone display, shortcuts.
 * - Service worker: precaches the app shell so the installed app opens offline. FPL data is NOT
 *   cached by the service worker — the browser query cache (src/app/persistence.ts) does that, so
 *   there is one cache with clear "saved data" notices instead of two.
 * - registerType 'autoUpdate' (owner's decision): a new version activates as soon as it has
 *   downloaded and open pages reload by themselves (src/app/PwaAutoUpdate.tsx), so nobody stays
 *   on an old version.
 */
export const pwaOptions: Partial<VitePWAOptions> = {
  registerType: 'autoUpdate',
  injectRegister: false, // registered from React (virtual:pwa-register/react)
  includeAssets: ['favicon.svg', 'favicon.ico', 'apple-touch-icon-180x180.png'],
  manifest: {
    id: '/',
    name: 'FPL Analysis',
    short_name: 'FPL Analysis',
    description:
      'Monthly prizes for our FPL mini-league and fixture difficulty for the next 5 GWs.',
    lang: 'en',
    dir: 'ltr',
    start_url: '/',
    scope: '/',
    display: 'standalone',
    orientation: 'any',
    background_color: '#f8fafc',
    theme_color: THEME_COLOR,
    categories: ['sports'],
    icons: [
      { src: 'pwa-64x64.png', sizes: '64x64', type: 'image/png' },
      { src: 'pwa-192x192.png', sizes: '192x192', type: 'image/png' },
      { src: 'pwa-512x512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
      {
        src: 'maskable-icon-512x512.png',
        sizes: '512x512',
        type: 'image/png',
        purpose: 'maskable',
      },
    ],
    shortcuts: [
      {
        name: 'Mini-league',
        url: '/league',
        icons: [{ src: 'pwa-192x192.png', sizes: '192x192', type: 'image/png' }],
      },
      {
        name: 'Current gameweek',
        short_name: 'Current GW',
        url: '/gameweek',
        icons: [{ src: 'pwa-192x192.png', sizes: '192x192', type: 'image/png' }],
      },
      {
        name: 'Fixture difficulty',
        short_name: 'FDR',
        url: '/fdr',
        icons: [{ src: 'pwa-192x192.png', sizes: '192x192', type: 'image/png' }],
      },
    ],
  },
  workbox: {
    globPatterns: ['**/*.{js,css,html,svg,png,ico,webmanifest}'],
    // SPA: any page URL opens the app shell offline — except the FPL proxy.
    navigateFallback: '/index.html',
    navigateFallbackDenylist: [/^\/api\//],
    cleanupOutdatedCaches: true,
    // Take over open pages at once (forced update).
    skipWaiting: true,
    clientsClaim: true,
  },
  devOptions: { enabled: false },
};
